// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { ICOURFeeVault } from "./interfaces/ICOURFeeVault.sol";
import { ICOURToken } from "./interfaces/ICOURToken.sol";
import { Constants } from "./libraries/Constants.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

/// @title COURToken
/// @notice Fixed-supply (1e9, 18 decimals) ERC-20 + Permit launched by the COUR factory. The entire
///         supply is minted once to the bonding curve. No mint, no burn, no owner, no blacklist,
///         no pause, no transfer tax.
/// @dev In HOLDERS mode, `holderRewards` is the FeeVault and every balance change notifies it BEFORE
///      balances move so the dividend accounting settles correctly. The vault keys that accounting by
///      msg.sender (this token), so it is safe even for the initial mint and needs no pre-registration.
contract COURToken is ERC20, ERC20Permit, ICOURToken {
    address public immutable factory;
    address public immutable curve;
    address public immutable stock;
    address public immutable creator;
    /// @inheritdoc ICOURToken
    address public immutable holderRewards; // FeeVault in HOLDERS mode, else address(0)

    string internal _metadataURI;

    /// @param holderRewards_ FeeVault address if mode == HOLDERS, else address(0).
    constructor(
        string memory name_,
        string memory symbol_,
        string memory metadataURI_,
        address curve_,
        address stock_,
        address creator_,
        address holderRewards_
    ) ERC20(name_, symbol_) ERC20Permit(name_) {
        factory = msg.sender;
        curve = curve_;
        stock = stock_;
        creator = creator_;
        holderRewards = holderRewards_;
        _metadataURI = metadataURI_;
        _mint(curve_, Constants.TOTAL_SUPPLY);
    }

    /// @inheritdoc ICOURToken
    function metadataURI() external view returns (string memory) {
        return _metadataURI;
    }

    /// @dev Notify the dividend vault before every balance change (HOLDERS mode only). The vault
    ///      function is O(1) and MUST NOT revert for normal transfers.
    function _update(address from, address to, uint256 value) internal override {
        address hr = holderRewards;
        if (hr != address(0)) {
            ICOURFeeVault(hr).beforeBalanceChange(from, to, value);
        }
        super._update(from, to, value);
    }
}

src/GraduationImpl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { FixedPointMathLib } from "solady/utils/FixedPointMathLib.sol";

import { IAllowanceTransfer } from "permit2/src/interfaces/IAllowanceTransfer.sol";
import { IPoolManager } from "v4-core/interfaces/IPoolManager.sol";
import { TickMath } from "v4-core/libraries/TickMath.sol";
import { Currency } from "v4-core/types/Currency.sol";
import { PoolKey } from "v4-core/types/PoolKey.sol";
import { IPositionManager } from "v4-periphery/src/interfaces/IPositionManager.sol";
import { Actions } from "v4-periphery/src/libraries/Actions.sol";
import { LiquidityAmounts } from "v4-periphery/src/libraries/LiquidityAmounts.sol";

import { ICOURFeeVault } from "./interfaces/ICOURFeeVault.sol";
import { Constants } from "./libraries/Constants.sol";
import { Errors } from "./libraries/Errors.sol";
import { PoolKeyLib } from "./libraries/PoolKeyLib.sol";

/// @title GraduationImpl
/// @notice Stateless implementation of the graduation pool-init + LP mint, executed by COURFactory via
///         DELEGATECALL so the heavy Uniswap v4 / Permit2 code lives OUTSIDE the factory bytecode (keeping
///         the factory under the EIP-170 24,576-byte limit). Because it runs in the factory's context,
///         `address(this)` is the factory: it initializes the pool as the factory (so the hook's
///         `beforeInitialize` sees `sender == factory`), spends the factory's token/stock balances, and
///         mints the full-range position NFT to DEAD. MUST declare NO storage variables.
contract GraduationImpl {
    using SafeERC20 for IERC20;

    /// @dev The impl's own deployed address, baked into its bytecode. Under a delegatecall `address(this)`
    ///      is the FACTORY (!= __self); a direct call has `address(this) == __self`. Lets graduate() reject
    ///      direct calls (defense-in-depth; a direct call is already inert — hook rejects non-factory init).
    address private immutable __self = address(this);

    struct Params {
        address token;
        address stock;
        address hook;
        address poolManager;
        address positionManager;
        address feeVault;
        // Curve accounting (NOT balanceOf) — the pool price and LP size are derived from these so that
        // any stock/token DONATED to the curve before graduation cannot move the initial pool price (L-4).
        uint256 vS0; // initial virtual stock reserve
        uint256 vT0; // initial virtual token reserve (== TOTAL_SUPPLY + virtual offset)
        uint256 vTStop; // graduation stop point for vT
        uint256 k; // vS0 * vT0
    }

    /// @dev Delegatecalled by the factory. Returns (positionId, tokenIntoPool, stockIntoPool) for the event.
    ///      The factory has already pulled the curve's FULL balances (accounting + any donations) into
    ///      itself; this routine sizes the LP from the curve's internal accounting and sweeps everything
    ///      left over (donations + rounding) to DEAD (tokens) / the platform bucket (stock).
    function graduate(Params calldata p)
        external
        returns (uint256 positionId, uint256 tokenLeftoverNet, uint256 stockRaisedNet)
    {
        if (address(this) == __self) revert Errors.OnlyDelegatecall(); // reject direct (non-delegatecall) calls
        (PoolKey memory key, bool tokenIsZero) = PoolKeyLib.build(p.token, p.stock, p.hook);

        // Accounting amounts (manipulation-proof): the real stock raised is the virtual-stock delta at the
        // stop (vsAtStop - vS0, exactly what the solvent curve holds), and the unsold tokens are
        // TOTAL_SUPPLY - (vT0 - vTStop) (the exact graduation token count, SP-04). Donations inflate the
        // factory's balanceOf above these but NEVER enter the price or the LP.
        uint256 acctStock = FixedPointMathLib.divUp(p.k, p.vTStop) - p.vS0;
        uint256 acctToken = Constants.TOTAL_SUPPLY - (p.vT0 - p.vTStop);
        (uint256 amount0, uint256 amount1) = tokenIsZero ? (acctToken, acctStock) : (acctStock, acctToken);

        // Initialize the pool at the reserve ratio (= graduation price). X128 encoding avoids the X192
        // overflow for low-decimal stock vs an 18-decimal token.
        uint256 ratioX128 = FixedPointMathLib.fullMulDiv(amount1, 1 << 128, amount0);
        uint160 sqrtPriceX96 = uint160(FixedPointMathLib.sqrt(ratioX128) << 32);
        IPoolManager(p.poolManager).initialize(key, sqrtPriceX96);

        // forge-lint: disable-next-line(divide-before-multiply)
        int24 tickLower = (TickMath.MIN_TICK / Constants.POOL_TICK_SPACING) * Constants.POOL_TICK_SPACING;
        // forge-lint: disable-next-line(divide-before-multiply)
        int24 tickUpper = (TickMath.MAX_TICK / Constants.POOL_TICK_SPACING) * Constants.POOL_TICK_SPACING;
        uint128 liq = LiquidityAmounts.getLiquidityForAmounts(
            sqrtPriceX96,
            TickMath.getSqrtPriceAtTick(tickLower),
            TickMath.getSqrtPriceAtTick(tickUpper),
            amount0,
            amount1
        );

        // Mint the full-range position NFT to DEAD via the PositionManager (paying via Permit2). The
        // approvals/maxes are the ACCOUNTING amounts, so the mint can never pull donated excess.
        uint256 tokenBeforeMint = IERC20(p.token).balanceOf(address(this));
        uint256 stockBeforeMint = IERC20(p.stock).balanceOf(address(this));
        positionId = IPositionManager(p.positionManager).nextTokenId();
        _permit2Approve(key.currency0, uint160(amount0), p.positionManager);
        _permit2Approve(key.currency1, uint160(amount1), p.positionManager);
        {
            bytes memory actions = abi.encodePacked(uint8(Actions.MINT_POSITION), uint8(Actions.SETTLE_PAIR));
            bytes[] memory params = new bytes[](2);
            params[0] = abi.encode(
                key, tickLower, tickUpper, uint256(liq), uint128(amount0), uint128(amount1), Constants.DEAD, bytes("")
            );
            params[1] = abi.encode(key.currency0, key.currency1);
            IPositionManager(p.positionManager).modifyLiquidities(abi.encode(actions, params), block.timestamp);
        }
        _permit2Approve(key.currency0, 0, p.positionManager);
        _permit2Approve(key.currency1, 0, p.positionManager);

        // Sweep EVERYTHING not consumed by the mint (donations + rounding dust): tokens -> DEAD, stock ->
        // platform bucket. Donated stock/tokens therefore leave the system / enrich the platform rather than
        // silently subsidising the burned LP at a manipulated price.
        uint256 tokenDust = IERC20(p.token).balanceOf(address(this));
        uint256 stockDust = IERC20(p.stock).balanceOf(address(this));
        if (tokenDust > 0) IERC20(p.token).safeTransfer(Constants.DEAD, tokenDust);
        if (stockDust > 0) {
            IERC20(p.stock).safeTransfer(p.feeVault, stockDust);
            ICOURFeeVault(p.feeVault).creditPlatform(p.stock, stockDust);
        }
        // Amounts actually placed into the pool (for the Graduated event).
        tokenLeftoverNet = tokenBeforeMint - tokenDust;
        stockRaisedNet = stockBeforeMint - stockDust;
    }

    function _permit2Approve(Currency currency, uint160 amount, address posm) private {
        address t = Currency.unwrap(currency);
        IERC20(t).forceApprove(Constants.PERMIT2, amount);
        IAllowanceTransfer(Constants.PERMIT2).approve(t, posm, amount, uint48(block.timestamp + 1));
    }
}

src/interfaces/ICOURCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { TokenConfig } from "../types/TokenConfig.sol";

/// @title ICOURCurve
/// @notice Virtual constant-product bonding curve (one EIP-1167 clone per token), priced in stock.
interface ICOURCurve {
    /// @notice Initialize the clone. Only the factory, once.
    function initialize(TokenConfig calldata cfg) external;

    /// @notice Tax-free (fee still applies) creator initial buy performed atomically in createToken.
    ///         Only the factory. Stock is pulled from the factory.
    function initialBuy(uint256 stockIn, uint256 minTokensOut, address to)
        external
        returns (uint256 tokensOut, uint256 stockUsed);

    /// @notice Buy tokens with `stockIn` gross stock (fee + launch tax applied inside).
    /// @return tokensOut tokens delivered to `to`.
    /// @return stockUsed gross stock actually consumed (may be < stockIn if the buy graduates with a refund).
    function buy(uint256 stockIn, uint256 minTokensOut, address to, uint256 deadline)
        external
        returns (uint256 tokensOut, uint256 stockUsed);

    /// @notice Sell `tokensIn` tokens for stock (fee applied inside, no launch tax).
    function sell(uint256 tokensIn, uint256 minStockOut, address to, uint256 deadline)
        external
        returns (uint256 stockOut);

    // --- quotes (views) ---
    function quoteBuy(uint256 stockIn) external view returns (uint256 tokensOut, uint256 fee, uint256 tax);
    function quoteSell(uint256 tokensIn) external view returns (uint256 stockOut, uint256 fee);
    function quoteStockForTokens(uint256 tokensWanted) external view returns (uint256 stockIn);

    /// @notice Progress toward graduation in bps (sold / soldAtStop).
    function progressBps() external view returns (uint256);

    function graduated() external view returns (bool);
    function vS() external view returns (uint256);
    function vT() external view returns (uint256);
    function config() external view returns (TokenConfig memory);
}

src/interfaces/ICOURFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { TokenConfig } from "../types/TokenConfig.sol";
import { ICOURPriceReader } from "./ICOURPriceReader.sol";

/// @title ICOURFactory
/// @notice Launches COUR tokens and graduates them into Uniswap v4 pools with the COUR hook.
interface ICOURFactory {
    struct CreateParams {
        string name;
        string symbol;
        string metadataURI;
        address stock; // must be allowlisted
        uint16 creatorFeeBps; // 100..1000
        uint8 creatorMode; // 0..3
        address feeRecipient; // creator-side recipient; defaults to msg.sender if zero
        uint256 initialBuyStock; // optional tax-free launch buy; capped at 50% supply
        uint256 minInitialTokens; // slippage bound for the initial buy
        bytes32 salt; // CREATE2 salt for a deterministic token address
    }

    function createToken(CreateParams calldata p) external payable returns (address token, address curve);

    /// @notice Build the graduation pool, add full-range liquidity, burn the position. Only the token's curve.
    function graduate(address token) external;

    // --- views used by curve / hook / vault ---
    function tokenConfig(address token) external view returns (TokenConfig memory);
    function curveOf(address token) external view returns (address);
    function isCOURToken(address token) external view returns (bool);
    function poolIdOf(address token) external view returns (bytes32);
    function hook() external view returns (address);
    function feeVault() external view returns (address);
    function priceReader() external view returns (ICOURPriceReader);
    function poolManager() external view returns (address);

    // --- admin ---
    function setStock(address stock, bool allowed, address refPool, ICOURPriceReader.RefKind kind) external;
    function setLaunchParams(uint256 startMcUsd, uint256 gradMcUsd, uint256 minRefLiqUsd, uint256 launchFee) external;
    function setLaunchesPaused(bool paused) external;
    function stockAllowed(address stock) external view returns (bool);

    /// @notice Gate NEW launches to an allowlist of creators (existing tokens are unaffected).
    function setLaunchAllowlist(address account, bool allowed) external;
    function setLaunchAllowlistEnabled(bool enabled) external;
    function launchAllowlistEnabled() external view returns (bool);
    function launchAllowlist(address account) external view returns (bool);
}

